using System;
using Outbreak.Contracts;
using Outbreak.Core;
public static partial class Program
{
    private static ShelterSupplyOverview SupplyRoom(World world,int id){return Array.Find(world.ShelterSupplies(),row=>row.RoomId==id);}
    private static void CheckShelterSupplyCases()
    {
        Check("Shelter supply census reports actual food hungry occupants and assigned trips read-only",()=>{
            World world=EncounterScenarios.ShelterShortageTest();string before=State(world);ShelterSupplyOverview[] rows=world.ShelterSupplies();Require(rows.Length==3 && rows[0].RoomId==81 && rows[1].RoomId==90 && rows[2].RoomId==99,"Shelter supply rows lost stable geometry order.");ShelterSupplyOverview first=rows[0],second=rows[1],empty=rows[2];Require(first.Occupants==2 && first.Hungry==2 && first.VeryHungry==1 && first.Meals==0 && first.ReserveDeficit==6 && first.RestockingTrips==1 && first.Status=="NO FOOD" && first.NeedsAttention,"Occupied empty shelter shortage was misclassified.");Require(second.Occupants==1 && second.CarriedMeals==1 && second.BoxMeals==6 && second.ShelfMeals==4 && second.Meals==11 && second.Status=="SUPPLIED" && !second.NeedsAttention,"Supplied room double-counted food or missed unopened shelf stock.");Require(empty.Occupants==0 && empty.ReserveDeficit==6 && empty.Status=="UNOCCUPIED" && !empty.NeedsAttention,"Unused empty building raised a shortage alarm.");Require(State(world)==before && world.ActorAt(0).storageMemory==null && world.FoodSupplies().RemainingMeals==24,"Player census changed knowledge, inventory or outside supply totals.");rows[0].Occupants=999;Require(SupplyRoom(world,81).Occupants==2,"Returned supply rows aliased authoritative state.");
        });
        Check("Shelter supply thresholds distinguish meals per occupant from box reserve gaps",()=>{
            World world=EncounterScenarios.ShelterShortageTest();SaveDocument saved=world.Capture();saved.actors[0].carriedFood=1;world=World.Restore(saved);Require(SupplyRoom(world,81).Status=="LOW FOOD" && SupplyRoom(world,81).ShortOnMeals,"One meal for two occupants was not low food.");saved.actors[1].carriedFood=1;world=World.Restore(saved);Require(SupplyRoom(world,81).Status=="BELOW RESERVE" && !SupplyRoom(world,81).ShortOnMeals && SupplyRoom(world,81).NeedsAttention,"Adequate immediate food obscured an unfilled box target.");Require(world.TrySetStorageFoodReserve(4,3,0),"Could not turn off test reserve.");ShelterSupplyOverview row=SupplyRoom(world,81);Require(row.Status=="SUPPLIED" && row.Hungry==2 && row.ReserveDeficit==0 && !row.NeedsAttention,"Hunger alone was mislabeled a food shortage despite available meals and no reserve goal.");saved=EncounterScenarios.ShelterShortageTest().Capture();world=World.Restore(saved);world.TrySetStorageFoodReserve(4,3,0);Require(SupplyRoom(world,81).Status=="NO FOOD" && SupplyRoom(world,81).NeedsAttention,"Disabling restocking hid an actual empty-food shortage.");
        });
        Check("Shelter supply census excludes corpses zombies and inbound humans from occupancy",()=>{
            World world=EncounterScenarios.ShelterShortageTest();int id;Require(world.TrySpawn(Species.Human,2,6,out id) && world.TrySpawn(Species.Zombie,12,6,out id),"Could not arrange census exclusions.");SaveDocument saved=world.Capture();saved.actors[4].health=0;world=World.Restore(saved);Require(SupplyRoom(world,81).Occupants==2 && SupplyRoom(world,90).Occupants==1,"Corpse or zombie counted as a human food consumer.");saved.actors[2].x=9;saved.actors[2].shelterState=ShelterState.Seeking;world=World.Restore(saved);Require(SupplyRoom(world,90).Occupants==0 && SupplyRoom(world,90).CarriedMeals==0,"Inbound reservation or outside carried meals counted as physically inside.");saved.actors[3].x=2;saved.actors[3].y=7;world=World.Restore(saved);Require(SupplyRoom(world,81).Occupants==3 && SupplyRoom(world,81).CarriedMeals==1 && SupplyRoom(world,81).RestockingTrips==1,"Physical unassigned occupant was missed or an in-room restocker was counted twice.");
        });
        Check("Reserve gaps remain per-box and active away restockers keep their shortage visible",()=>{
            SaveDocument saved=EncounterScenarios.ShelterShortageTest().Capture();WorldMap map=WorldMap.Restore(saved.map);map.SetStorageBox(new StorageBoxDocument{x=4,y=6,capacity=30,items=new[]{new ItemStackDocument{item=InventoryItem.Food,quantity=8}}});saved.map=map.Capture();World world=World.Restore(saved);ShelterSupplyOverview row=SupplyRoom(world,81);Require(row.BoxMeals==8 && row.Boxes==2 && row.BoxesBelowTarget==1 && row.ReserveDeficit==6 && row.Status=="BELOW RESERVE","Surplus in another box incorrectly cancelled an individual box's target.");saved=EncounterScenarios.ShelterShortageTest().Capture();saved.actors=new[]{saved.actors[3]};world=World.Restore(saved);row=SupplyRoom(world,81);Require(row.Occupants==0 && row.RestockingTrips==1 && row.NeedsAttention && row.Status=="BELOW RESERVE","Temporarily empty home disappeared while its restocker was away.");
        });
        Check("Shelter supply rows refresh after deposits meals conversion and save restore",()=>{
            World world=EncounterScenarios.StorageSupplyTest();ShelterSupplyOverview before=world.ShelterSupplies()[0];world.Step();ShelterSupplyOverview after=world.ShelterSupplies()[0];Require(before.Meals==3 && after.Meals==3 && before.ReserveDeficit==6 && after.ReserveDeficit==4 && after.BoxMeals==2 && after.CarriedMeals==1,"Deposit failed to update room stock without double counting.");world=EncounterScenarios.StorageSupplyTest(true);world.Step();Require(world.ShelterSupplies()[0].Meals==6,"Withdrawing food changed the room's total meal count.");Run(world,5);Require(world.ShelterSupplies()[0].Meals==5,"Eating did not decrement the room's real meal total.");World copy=World.Restore(world.Capture());Require(copy.ShelterSupplies()[0].Meals==5 && copy.ShelterSupplies()[0].ReserveDeficit==3,"Loading did not rebuild current supply rows.");SaveDocument saved=world.Capture();saved.actors[0].turnAtTick=saved.tick+1;world=World.Restore(saved);world.Step();Require(world.ShelterSupplies()[0].Occupants==0 && world.ShelterSupplies()[0].Status=="UNOCCUPIED" && !world.ShelterSupplies()[0].NeedsAttention,"Converted human retained a supply shortage alarm.");
        });
        Check("Supply reporting supports old food rules and empty room catalogs without rule changes",()=>{
            World world=new World(new WorldMap(10000,10000),214,encounter:true,hunger:true);Require(world.ShelterSupplies().Length==0,"Open terrain invented supply rooms.");world=new World(EncounterScenarios.MixedShelterMap(),214,encounter:true);Require(world.ShelterSupplies().Length==0,"Food-disabled runs exposed a food supply census.");SaveDocument saved=EncounterScenarios.ShelterShortageTest().Capture();saved.rulesVersion=EncounterRules.StorageVersion;saved.actors[3].restockPhase=RestockPhase.None;saved.actors[3].restockBox=0;saved.actors[3].restockHomeId=0;saved.actors[3].restockUntilTick=0;world=World.Restore(saved);string before=State(world);Require(SupplyRoom(world,81).ReserveDeficit==0 && SupplyRoom(world,81).Status=="NO FOOD" && State(world)==before && world.Capture().rulesVersion==EncounterRules.StorageVersion,"Reporting activated newer restocking rules or applied inactive reserve goals.");
        });
    }
}
